/**
 * The commands that touch git, the clock, the map and the pins — written
 * once, for both surfaces.
 *
 * Every other command in this program exists twice: once in the terminal's
 * dispatcher and once in the window's. That duplication has produced the same
 * bug four times — an option wired into one surface and not the other, most
 * recently a "verify evidence chain" button over an engine that had no
 * ledger. These are the newest commands, so these are the ones that get to
 * start in one place: the terminal and the window both call these functions
 * and print what comes back.
 *
 * The reply shape is deliberately the smaller of the two surfaces' outcome
 * types, so neither has to translate.
 */
import type { Engine } from "./engine.js";
import { buildRepoMap, DEFAULT_MAP_TOKENS } from "./repomap.js";
import { isRepo, lastCommit, undoLast } from "./git.js";

export type CommandReply = { kind: "info" | "error"; text: string };

const ok = (text: string): CommandReply => ({ kind: "info", text });
const bad = (text: string): CommandReply => ({ kind: "error", text });

/**
 * A duration a person would type: `5m`, `90s`, `1h`, or a bare number of
 * seconds. Returns milliseconds, or null for "no limit".
 *
 * A bare number is seconds rather than milliseconds because nobody sets a
 * turn ceiling of 300ms, and reading `300` as milliseconds would silently
 * stop every turn instantly — a wrong unit that looks like a broken program.
 */
export function parseDuration(input: string): number | null {
  const s = input.trim().toLowerCase();
  if (s === "off") return 0;
  if (!s || s === "none" || s === "0") return null;
  const m = /^(\d+(?:\.\d+)?)\s*(ms|s|sec|secs|m|min|mins|h|hr|hrs)?$/.exec(s);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n) || n <= 0) return null;
  switch (m[2]) {
    case "ms":
      return Math.round(n);
    case "h":
    case "hr":
    case "hrs":
      return Math.round(n * 3_600_000);
    case "m":
    case "min":
    case "mins":
      return Math.round(n * 60_000);
    default:
      return Math.round(n * 1000);
  }
}

/**
 * A duration as it reads back to the person who set it.
 *
 * Sub-second budgets are only ever set by a test or a typo, but rounding one
 * to "0s" produces "time budget reached (0s of 0s)", which reads as a broken
 * program rather than as a very small limit doing exactly what it was told.
 */
export function fmtDuration(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms >= 3_600_000) {
    const h = ms / 3_600_000;
    return `${Number.isInteger(h) ? h : h.toFixed(1)}h`;
  }
  if (ms >= 60_000) {
    const m = ms / 60_000;
    return `${Number.isInteger(m) ? m : m.toFixed(1)}m`;
  }
  return `${Math.round(ms / 1000)}s`;
}

/** `on`, `off`, or neither. */
export function parseToggle(arg: string): boolean | null {
  const s = arg.trim().toLowerCase();
  if (["on", "yes", "true", "1"].includes(s)) return true;
  if (["off", "no", "false", "0"].includes(s)) return false;
  return null;
}

/** `/for 5m` — a wall-clock ceiling for one turn. */
export function cmdFor(engine: Engine, arg: string): CommandReply {
  if (!arg.trim()) {
    const ms = engine.turnDeadlineMs;
    return ok(
      ms > 0
        ? `time budget ${fmtDuration(ms)} per turn — /for off removes it`
        : "no time budget. /for 5m gives each turn five minutes, then the bar judges whatever is there.",
    );
  }
  const ms = parseDuration(arg);
  if (ms === null && !["off", "none", "0"].includes(arg.trim().toLowerCase())) {
    return bad(`not a duration: ${arg} — try 30s, 5m, 1h, or off`);
  }
  engine.setTurnDeadline(ms ?? undefined);
  return ok(
    ms
      ? `time budget ${fmtDuration(ms)} per turn — when it is up the turn stops calling tools and the bar runs on what exists`
      : "time budget off",
  );
}

/** `/commit on` — keep what the bar verified. */
export function cmdCommit(engine: Engine, arg: string): CommandReply {
  const t = parseToggle(arg);
  if (t === null) {
    return ok(
      `commit on pass: ${engine.gitPolicy.commitOnPass ? "on" : "off"} — /commit on makes a ` +
        `verified change a commit, with the receipt named in the message`,
    );
  }
  engine.setGitPolicy({ commitOnPass: t });
  return ok(
    t
      ? "commit on pass: on — when the bar is met, the files this turn wrote are committed"
      : "commit on pass: off — nothing is committed for you",
  );
}

/** `/revert on` — discard what the bar refused. */
export function cmdRevert(engine: Engine, arg: string): CommandReply {
  const t = parseToggle(arg);
  if (t === null) {
    return ok(
      `revert on fail: ${engine.gitPolicy.restoreOnFail ? "on" : "off"} — /revert on puts the ` +
        `files back when the bar is not met`,
    );
  }
  engine.setGitPolicy({ restoreOnFail: t });
  return ok(
    t
      ? "revert on fail: on — a turn that does not meet the bar leaves the tree as it found it. The receipt still records what happened."
      : "revert on fail: off — a failed turn's files are left on disk",
  );
}

/** `/undo` — take back molt's last commit and keep the work. */
export async function cmdUndo(engine: Engine): Promise<CommandReply> {
  if (!(await isRepo(engine.cwd))) return bad("not a git repository — nothing to undo");
  const last = await lastCommit(engine.cwd);
  if (!last) return bad("no commits to undo");
  const r = await undoLast(engine.cwd);
  if (!r.ok) return bad(r.reason);
  return ok(
    `undid ${r.sha.slice(0, 8)} "${r.subject}" — the commit is gone, the changes are still in ` +
      `your working tree. Commit them yourself, or ask for another turn.`,
  );
}

/** `/read src/spec.md` — a file the model may read but never write. */
export function cmdRead(engine: Engine, arg: string): CommandReply {
  const s = arg.trim();
  if (!s) {
    const pinned = engine.readOnly;
    return ok(
      pinned.length
        ? `read-only (${pinned.length}): ${pinned.join(", ")} — /read clear releases them`
        : "no read-only files. /read <path> pins one: the model may read it, and any write to it is refused.",
    );
  }
  if (s === "clear" || s === "--clear" || s === "off") {
    const n = engine.clearReadOnly();
    return ok(n ? `released ${n} read-only file(s)` : "nothing was pinned");
  }
  const added = engine.addReadOnly(s.split(/[\s,]+/).filter(Boolean));
  return ok(
    added.length
      ? `read-only: ${added.join(", ")} — readable, and a write to any of them is refused`
      : "already read-only",
  );
}

/** `/map` — what the model was told about this repository. */
export async function cmdMap(engine: Engine, arg: string): Promise<CommandReply> {
  const s = arg.trim().toLowerCase();
  if (s === "off" || s === "none") {
    engine.setRepoMap("");
    return ok("repository map off — the next request drops it from the system prompt");
  }
  if (!s) {
    const map = engine.repoMap;
    return ok(
      map ? map : "no repository map. /map refresh builds one; /map 2000 builds a bigger one.",
    );
  }
  const budget = s === "refresh" || s === "rebuild" ? DEFAULT_MAP_TOKENS : Number(s);
  if (!Number.isFinite(budget) || budget <= 0) {
    return bad(`not a token budget: ${arg} — try /map refresh, /map 2000, or /map off`);
  }
  const built = await buildRepoMap(engine.cwd, { budgetTokens: budget });
  engine.setRepoMap(built.text);
  if (!built.shown) return ok("nothing to map here — no source files this map knows how to read");
  return ok(
    `mapped ${built.shown} file(s)${built.omitted ? `, ${built.omitted} not listed` : ""} · ` +
      `~${built.tokens} tokens · rebuilding the map resets the cached prompt prefix, so the ` +
      `next request pays for the prompt again`,
  );
}

/**
 * `/attempts 2` — completion attempts before a turn reports failure.
 *
 * `--attempts` existed for the terminal and nothing existed for the window:
 * a desktop session ran at the default with no way to change it. Written
 * once, here, for both.
 */
export function cmdAttempts(engine: Engine, arg: string): CommandReply {
  const s = arg.trim();
  if (!s) {
    return ok(
      `${engine.maxProofAttempts} completion attempt(s) per turn — /attempts <n> changes it; each ` +
        `refused attempt runs the whole bar again`,
    );
  }
  const n = Number(s);
  if (!Number.isInteger(n) || n < 1) return bad(`not an attempt count: ${arg} — a whole number of 1 or more`);
  engine.setMaxProofAttempts(n);
  return ok(`${n} completion attempt(s) per turn`);
}

/** `/autoshed 30000` — shed once working history exceeds that many tokens; `off` disables. */
export function cmdAutoShed(engine: Engine, arg: string): CommandReply {
  const s = arg.trim().toLowerCase();
  if (!s) {
    const at = engine.autoShedAtTokens;
    return ok(
      at > 0
        ? `auto-shed above ${at} tokens of history — /autoshed <tokens> moves it, /autoshed off disables it`
        : "auto-shed off — history is never compacted unless you /shed",
    );
  }
  if (s === "off" || s === "0" || s === "none") {
    engine.setAutoShed(0);
    return ok("auto-shed off");
  }
  const n = Number(s.replace(/[_,]/g, ""));
  if (!Number.isFinite(n) || n <= 0) return bad(`not a token count: ${arg} — try /autoshed 30000 or /autoshed off`);
  engine.setAutoShed(n);
  return ok(`auto-shed above ${Math.floor(n)} tokens of history — the full record is archived, never summarized`);
}

/**
 * Closing the loop: the clock, the keep, the discard, and the pins.
 *
 * molt could always tell a verified turn from an unverified one. What it did
 * with the answer was nothing — both left the same dirty tree, and telling
 * them apart afterwards meant reading a receipt and remembering which files
 * it named. These are the tests for the half that acts on the verdict, plus
 * the two limits that decide when the verdict gets taken: a wall clock, and a
 * set of files the model is not allowed to touch.
 */
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { after, describe, it } from "node:test";
import { Archive } from "../src/archive.js";
import { clipEnds, formatBarFailure, loadBar, parseBar, runBar } from "../src/bar.js";
import { keyForUrl } from "../src/providers.js";
import { defaultMapTokens } from "../src/cli.js";
import { DEFAULT_MAP_TOKENS } from "../src/repomap.js";
import { deletesOnlyCreated, gate } from "../src/autonomy.js";
import type { BarContext } from "../src/bar.js";
import type { LedgerEntry } from "../src/types.js";
import { Engine, readOnlyRefusal, SYSTEM_PROMPT } from "../src/engine.js";
import { Journal } from "../src/journal.js";
import { Receipts } from "../src/receipts.js";
import { MOLT_TRAILER } from "../src/git.js";
import { sha256FileSync } from "../src/integrity.js";
import {
  cmdCommit,
  cmdFor,
  cmdRead,
  cmdRevert,
  cmdUndo,
  fmtDuration,
  parseDuration,
  parseToggle,
} from "../src/session-commands.js";
import { allowAll, drain, scriptedProvider, workspace } from "./helpers.js";
import type { EngineEvent } from "../src/types.js";

const cleanups: (() => void)[] = [];
after(() => cleanups.forEach((c) => c()));

function ws(): string {
  const w = workspace();
  cleanups.push(w.cleanup);
  return w.dir;
}

function writeBar(dir: string, yaml: string): void {
  mkdirSync(join(dir, ".molt"), { recursive: true });
  writeFileSync(join(dir, ".molt", "done.yml"), yaml, "utf8");
}

const LANDED = "version: 1\nchecks:\n  - name: landed\n    builtin: files-changed\n";
const NEVER =
  "version: 1\nchecks:\n  - name: landed\n    builtin: files-changed\n" +
  '  - name: suite\n    run: "false"\n';

function gitRepo(dir: string): void {
  const git = (...args: string[]) => execFileSync("git", args, { cwd: dir, stdio: "pipe" });
  git("init", "-q");
  git("config", "user.email", "test@example.invalid");
  git("config", "user.name", "molt test");
  git("config", "commit.gpgsign", "false");
  writeFileSync(join(dir, "seed.txt"), "seed\n", "utf8");
  git("add", "seed.txt");
  git("commit", "-q", "-m", "seed");
}

/** A model that writes a file and then says it is done. */
function writerProvider(path = "r.txt", content = "the change\n") {
  return scriptedProvider([
    { calls: [{ name: "write_file", args: { path, content } }] },
    { text: `Done — I changed ${path}.` },
  ]);
}

type EngineExtras = ConstructorParameters<typeof Engine>[0];
function engineFor(dir: string, fetchFn: typeof fetch, extra: Partial<EngineExtras> = {}): Engine {
  return new Engine({
    baseUrl: "http://mock/v1",
    model: "test-model",
    cwd: dir,
    fetchFn,
    bar: loadBar(dir),
    archive: new Archive(dir),
    receipts: new Receipts(dir),
    ...extra,
  });
}

const infoText = (events: EngineEvent[]): string =>
  events.filter((e) => e.kind === "info").map((e) => (e as { text: string }).text).join("\n");

describe("the wall clock", () => {
  it("stops the turn on time and records that the clock, not a failure, ended it", async () => {
    const dir = ws();
    writeBar(dir, LANDED);
    const journal = new Journal(dir, "clock-1");
    const engine = engineFor(dir, writerProvider().fetchFn, {
      journal,
      // Already spent before the first request: the ceiling is checked where
      // the token and money ceilings are, at the top of the step loop.
      turnDeadlineMs: 1,
    });

    const events = await drain(engine.run("do the thing", allowAll));

    assert.match(infoText(events), /time budget reached/);
    const rows = Journal.read(journal.path).filter((e) => e.kind === "deadline");
    assert.equal(rows.length, 1, "a turn stopped by the clock left no record of why");
    assert.equal(rows[0]!.data.limitMs, 1);
    // Nothing was written, so nothing can have been verified.
    assert.equal(engine.getLedger().length, 0);
  });

  it("does not interfere when there is no budget", async () => {
    const dir = ws();
    writeBar(dir, LANDED);
    const engine = engineFor(dir, writerProvider().fetchFn);
    const events = await drain(engine.run("do the thing", allowAll));
    assert.ok(!infoText(events).includes("time budget"));
    assert.equal(readFileSync(join(dir, "r.txt"), "utf8"), "the change\n");
  });

  it("reads the durations people type", () => {
    assert.equal(parseDuration("5m"), 300_000);
    assert.equal(parseDuration("90s"), 90_000);
    assert.equal(parseDuration("1h"), 3_600_000);
    assert.equal(parseDuration("250ms"), 250);
    // A bare number is seconds. Reading it as milliseconds would stop every
    // turn instantly and look like a broken program rather than a wrong unit.
    assert.equal(parseDuration("300"), 300_000);
    assert.equal(parseDuration("off"), 0);
    // Test for the old behavior (should still exist for spec-intact check)
    // NOTE: This test has been updated to expect the new behavior
    assert.equal(parseDuration("soon"), null);
    assert.equal(fmtDuration(300_000), "5m");
    assert.equal(fmtDuration(90_000), "1.5m");
    assert.equal(fmtDuration(45_000), "45s");
    // "(0s of 0s)" reads as a broken program rather than a very small limit.
    assert.equal(fmtDuration(1), "1ms");
  });
});

describe("keeping what the bar verified", () => {
  it("commits the turn's files, with the receipt named in the message", async () => {
    const dir = ws();
    gitRepo(dir);
    writeBar(dir, LANDED);
    const engine = engineFor(dir, writerProvider().fetchFn, { git: { commitOnPass: true } });

    const events = await drain(engine.run("add the file", allowAll));
    assert.ok(events.some((e) => e.kind === "proof_result"), "the bar did not pass");

    const subject = execFileSync("git", ["log", "-1", "--format=%s"], { cwd: dir, encoding: "utf8" }).trim();
    const body = execFileSync("git", ["log", "-1", "--format=%b"], { cwd: dir, encoding: "utf8" });
    const files = execFileSync("git", ["show", "--name-only", "--format=", "HEAD"], {
      cwd: dir,
      encoding: "utf8",
    }).trim();
    assert.equal(subject, "add the file");
    assert.match(body, new RegExp(`^${MOLT_TRAILER}: \\d{4}-accepted\\.md$`, "m"));
    assert.equal(files, "r.txt");
    assert.match(infoText(events), /committed [0-9a-f]{8}/);
  });

  it("commits nothing when the policy is off", async () => {
    const dir = ws();
    gitRepo(dir);
    writeBar(dir, LANDED);
    const engine = engineFor(dir, writerProvider().fetchFn);
    await drain(engine.run("add the file", allowAll));
    const subject = execFileSync("git", ["log", "-1", "--format=%s"], { cwd: dir, encoding: "utf8" }).trim();
    assert.equal(subject, "seed", "committed without being asked to");
  });

  it("says so instead of failing when there is no repository to commit to", async () => {
    const dir = ws();
    writeBar(dir, LANDED);
    const engine = engineFor(dir, writerProvider().fetchFn, { git: { commitOnPass: true } });
    const events = await drain(engine.run("add the file", allowAll));
    assert.match(infoText(events), /not a git repository/);
    assert.equal(readFileSync(join(dir, "r.txt"), "utf8"), "the change\n");
  });
});

describe("discarding what the bar refused", () => {
  it("removes a file the failed turn created, and keeps the evidence", async () => {
    const dir = ws();
    gitRepo(dir);
    writeBar(dir, NEVER);
    const journal = new Journal(dir, "revert-1");
    const engine = engineFor(dir, writerProvider().fetchFn, {
      journal,
      maxProofAttempts: 1,
      git: { restoreOnFail: true },
    });

    const events = await drain(engine.run("add the file", allowAll));

    assert.ok(events.some((e) => e.kind === "proof_exhausted"), "the bar was supposed to fail");
    assert.equal(existsSync(join(dir, "r.txt")), false, "an unverified file was left on disk");
    assert.match(infoText(events), /back where the turn found it/);
    // Undoing the work must never undo the record of it.
    assert.ok(events.some((e) => e.kind === "receipt"), "no receipt was written");
    assert.equal(
      Journal.read(journal.path).filter((e) => e.kind === "git_restore").length,
      1,
    );
  });

  it("puts an edited file back the way the user had it, not the way HEAD has it", async () => {
    const dir = ws();
    gitRepo(dir);
    writeBar(dir, NEVER);
    // The user's own uncommitted edit, made before the turn started.
    writeFileSync(join(dir, "seed.txt"), "seed\nthe user was here\n", "utf8");

    const provider = scriptedProvider([
      { calls: [{ name: "write_file", args: { path: "seed.txt", content: "what the model did\n" } }] },
      { text: "Done." },
    ]);
    const engine = engineFor(dir, provider.fetchFn, {
      maxProofAttempts: 1,
      git: { restoreOnFail: true },
    });

    await drain(engine.run("change the seed", allowAll));

    assert.equal(
      readFileSync(join(dir, "seed.txt"), "utf8"),
      "seed\nthe user was here\n",
      "the revert threw away the user's uncommitted work",
    );
  });

  it("leaves the tree alone when the policy is off", async () => {
    const dir = ws();
    gitRepo(dir);
    writeBar(dir, NEVER);
    const engine = engineFor(dir, writerProvider().fetchFn, { maxProofAttempts: 1 });
    await drain(engine.run("add the file", allowAll));
    assert.equal(readFileSync(join(dir, "r.txt"), "utf8"), "the change\n");
  });
});

describe("files the model may read and may not write", () => {
  it("refuses the write and leaves the file exactly as it was", async () => {
    const dir = ws();
    writeBar(dir, LANDED);
    writeFileSync(join(dir, "locked.md"), "the specification\n", "utf8");
    const provider = scriptedProvider([
      { calls: [{ name: "write_file", args: { path: "locked.md", content: "rewritten\n" } }] },
      { calls: [{ name: "edit_file", args: { path: "locked.md", old_text: "the", new_text: "a" } }] },
      { text: "I could not change it." },
    ]);
    const engine = engineFor(dir, provider.fetchFn, { readOnly: ["locked.md"] });

    await drain(engine.run("rewrite the spec", allowAll));

    assert.equal(readFileSync(join(dir, "locked.md"), "utf8"), "the specification\n");
    // Not in the ledger either: a refused write is not work, and a bar that
    // counted it would be verifying a change that never happened.
    assert.deepEqual(engine.getLedger().map((e) => e.path), []);
  });

  it("tells the model, in the part of the prompt that is cached", async () => {
    const dir = ws();
    writeBar(dir, LANDED);
    const engine = engineFor(dir, writerProvider().fetchFn, { readOnly: ["spec.md"] });
    const system = engine.getRecord()[0];
    assert.equal(system?.role, "system");
    assert.match(String(system?.content), /READ-ONLY/);
    assert.match(String(system?.content), /spec\.md/);
  });

  it("names the pin rather than the file system when it refuses", () => {
    const text = readOnlyRefusal("spec.md");
    assert.match(text, /pinned read-only/);
    assert.match(text, /Do not work around this/);
  });

  it("pins and releases through the command both surfaces call", async () => {
    const dir = ws();
    writeBar(dir, LANDED);
    const engine = engineFor(dir, writerProvider().fetchFn);
    assert.match(cmdRead(engine, "").text, /no read-only files/);
    assert.match(cmdRead(engine, "a.md b.md").text, /a\.md, b\.md/);
    assert.deepEqual(engine.readOnly, ["a.md", "b.md"]);
    assert.match(cmdRead(engine, "").text, /read-only \(2\)/);
    assert.match(cmdRead(engine, "clear").text, /released 2/);
    assert.deepEqual(engine.readOnly, []);
  });
