/**
 * Test for the src: coverage path matching ignores file extensions.
 *
 * This test demonstrates the bug where coverageFor fails to match source
 * files (src/bar.ts) with their compiled counterparts (dist-test/src/bar.js)
 * because the extension comparison (.ts vs .js) prevents a match.
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { coverageFor, parseLcov } from "../src/coverage.js";

const SOURCE_COV = `TN:
SF:dist-test/src/bar.js
DA:5,3
DA:6,0
DA:7,2
end_of_record
`;

describe("coverage path matching with extension differences", () => {
  it("matches source files to compiled files when extensions differ", () => {
    // The ledger has src/bar.ts (source), coverage has dist-test/src/bar.js (compiled).
    // Without extension-aware matching, this returns null and the check passes.
    const cov = parseLcov(SOURCE_COV);
    const result = coverageFor(cov, "src/bar.ts");
    assert.ok(result !== null, "should match src/bar.ts to dist-test/src/bar.js despite .ts vs .js extension");
    assert.equal(result!.lines.get(5), 3);
  });

  it("matches when source path is shorter than coverage path", () => {
    // Coverage reports dist-test/src/bar.js but the ledger has src/bar.ts.
    // The matching needs to work when wantParts is a prefix of keyParts (excluding extension).
    const cov = parseLcov(SOURCE_COV);
    const result = coverageFor(cov, "src/bar.ts");
    assert.ok(result !== null);
  });

  it("still refuses matches on filename alone (collision protection)", () => {
    // Different directories with same filename should not match.
    const cov = parseLcov("SF:vendor/bar.js\nDA:1,1\nend_of_record\n");
    // src/bar.ts should not match vendor/bar.js
    assert.equal(coverageFor(cov, "src/bar.ts"), null);
  });
});

/**
 * Asking whether anything executes the code a turn added.
 *
 * The gap the other builtins leave. `files-changed` proves a file moved;
 * `substance` proves the movement was not only comments. Neither can tell
 * whether the new code does anything.
 *
 * The change that motivated this passed six checks — types, tests, both app
 * checks, record-intact and work-landed — and was caught by a person reading
 * the diff:
 *
 *     export const MAX_COMMAND_LENGTH = 16384;           // referenced nowhere
 *     if (path.length > MAX_PATH_LENGTH) return false;   // branch never taken
 *
 * Reading diffs by hand does not scale, and is the job molt exists to replace.
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { readFileSync } from "node:fs";
import { parseLcov, coverageFor, unprovenIn, normalise } from "../src/coverage.js";

const LCOV = `TN:
SF:dist/src/files.js
DA:10,5
DA:11,0
DA:12,3
BRDA:12,0,0,4
BRDA:12,0,1,0
BRDA:14,1,0,2
DA:14,2
end_of_record
TN:
SF:dist/src/other.js
DA:1,1
end_of_record
`;

describe("reading lcov", () => {
  it("takes line and branch counts per file", () => {
    const cov = parseLcov(LCOV);
    assert.equal(cov.size, 2);
    const f = cov.get("dist/src/files.js")!;
    assert.equal(f.lines.get(10), 5);
    assert.equal(f.lines.get(11), 0);
    assert.deepEqual(f.branches.get(12), [4, 0]);
  });

  it("treats an unreached branch, written as '-', as zero", () => {
    const cov = parseLcov("SF:a/b.js\nBRDA:3,0,0,-\nend_of_record\n");
    assert.deepEqual(cov.get("a/b.js")!.branches.get(3), [0]);
  });

  it("skips records it does not know rather than throwing", () => {
    // A coverage tool gaining a record type must not break a build.
    const cov = parseLcov("SF:a/b.js\nWHAT:1,2\nDA:1,1\nend_of_record\n");
    assert.equal(cov.get("a/b.js")!.lines.get(1), 1);
  });

  it("survives an empty or malformed report", () => {
    assert.equal(parseLcov("").size, 0);
    assert.equal(parseLcov("DA:1,1\n").size, 0, "records before any SF belong to no file");
  });
});

describe("matching a project path to a coverage path", () => {
  it("matches through a build directory", () => {
    // Coverage is reported against whatever ran — usually compiled output.
    // Requiring equality would make this check impossible on any project with
    // a build step, which is most of them.
    const cov = parseLcov(LCOV);
    assert.ok(coverageFor(cov, "src/files.ts".replace(".ts", ".js")));
    assert.ok(coverageFor(cov, "src/files.js"));
  });

  it("refuses a match on the filename alone", () => {
    // `files.js` in two different directories is a collision, not a match, and
    // reporting one file's coverage for another would be worse than silence.
    const cov = parseLcov("SF:vendor/deep/nested/files.js\nDA:1,1\nend_of_record\n");
    assert.equal(coverageFor(cov, "files.js"), null);
  });

  it("normalises separators and a leading ./", () => {
    assert.equal(normalise(String.raw`./src\a.ts`), "src/a.ts");
  });
});

describe("what counts as unproven", () => {
  it("flags a changed line the tests never executed", () => {
    const cov = parseLcov(LCOV);
    const bad = unprovenIn(cov, "src/files.js", [11]);
    assert.deepEqual(bad?.deadLines, [11]);
  });

  it("flags a line that ran but whose branch never went one way", () => {
    // This is the guard that returns false and is never tripped. Line coverage
    // alone calls it covered — the `if` executed. Only the branch count says
    // the behaviour was never shown.
    const cov = parseLcov(LCOV);
    const bad = unprovenIn(cov, "src/files.js", [12]);
    assert.deepEqual(bad?.deadBranches, [12]);
    assert.deepEqual(bad?.deadLines, []);
  });

  it("accepts a line that ran with every branch taken", () => {
    const cov = parseLcov(LCOV);
    assert.equal(unprovenIn(cov, "src/files.js", [10, 14]), null);
  });

  it("says nothing about a line the tool never instrumented", () => {
    // lcov lists only what the tool considers executable, so a type, an
    // import or a declaration is simply absent. Silence means "not
    // instrumented", not "not run", and failing on it would refuse honest work.
    const cov = parseLcov(LCOV);
    assert.equal(unprovenIn(cov, "src/files.js", [99]), null);
  });

  it("is handed a report in source coordinates, or it can match nothing", () => {
    // The suite compiles to dist-test/ and the ledger names src/*.ts. Without
    // source maps the report says `dist-test/src/bar.js` with compiled line
    // numbers, `coverageFor` matches by path suffix, and `bar.js` never
    // matches `bar.ts` — every work-proven row this project ever issued read
    // "0 changed file(s) executed by the tests" and passed. Both halves are
    // needed: tsc has to emit the maps and node has to be told to read them.
    const tsconfig = JSON.parse(readFileSync("tsconfig.test.json", "utf8")) as {
      compilerOptions?: { sourceMap?: boolean };
    };
    assert.equal(tsconfig.compilerOptions?.sourceMap, true, "tsconfig.test.json must emit source maps");
    const runner = readFileSync("test-run.mjs", "utf8");
    assert.match(runner, /"--enable-source-maps"/, "test-run.mjs must pass --enable-source-maps");
    assert.match(runner, /"--experimental-test-coverage"/);
  });

  it("says nothing about a file absent from the report", () => {
    const cov = parseLcov(LCOV);
    assert.equal(unprovenIn(cov, "ui/styles.css", [1, 2, 3]), null);
  });
});

/**
 * Reading coverage, so a change can be asked whether anything executes it.
 *
 * `work-landed` proves a file changed. `substance` proves the change was not
 * only comments. Neither can tell whether the new code does anything, and that
 * is where the remaining cosmetic changes live — a constant declared and never
 * referenced, a guard no test ever trips, a branch that exists so a diff exists.
 *
 * One real example, which is why this file is here. A turn added:
 *
 *     export const MAX_COMMAND_LENGTH = 16384;      // referenced nowhere
 *     if (path.length > MAX_PATH_LENGTH) return false;   // branch never taken
 *
 * Six checks passed on it: types, tests, both app checks, record-intact, and
 * work-landed. It was caught by a person reading the diff, which does not
 * scale and is the thing molt exists to replace.
 *
 * lcov, because every coverage tool emits it. Node's own test runner does
 * (`--test-reporter=lcov`), as do c8, nyc, pytest-cov, and go's cover with a
 * converter, so this is not tied to one language.
 */

export type FileCoverage = {
  /** line number -> times executed. Only lines the tool considers executable. */
  lines: Map<number, number>;
  /** line number -> counts for each branch on that line. */
  branches: Map<number, number[]>;
};

export type Coverage = Map<string, FileCoverage>;

/**
 * Parse lcov into per-file line and branch counts.
 *
 * Deliberately tolerant: an unrecognised record is skipped rather than thrown
 * on. A coverage format that gains a record type should not break a build.
 */
export function parseLcov(text: string): Coverage {
  const out: Coverage = new Map();
  let file: FileCoverage | null = null;
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (line.startsWith("SF:")) {
      file = { lines: new Map(), branches: new Map() };
      out.set(normalise(line.slice(3)), file);
      continue;
    }
    if (!file) continue;
    if (line.startsWith("DA:")) {
      const [n, hits] = line.slice(3).split(",");
      const ln = Number(n);
      if (Number.isFinite(ln)) file.lines.set(ln, Number(hits) || 0);
    } else if (line.startsWith("BRDA:")) {
      // BRDA:<line>,<block>,<branch>,<taken>   taken is "-" when never reached
      const parts = line.slice(5).split(",");
      const ln = Number(parts[0]);
      const taken = parts[3] === "-" ? 0 : Number(parts[3]) || 0;
      if (!Number.isFinite(ln)) continue;
      const list = file.branches.get(ln) ?? [];
      list.push(taken);
      file.branches.set(ln, list);
    } else if (line === "end_of_record") {
      file = null;
    }
  }
  return out;
}

/** Paths differ by prefix and separator between tools; compare by suffix. */
export function normalise(path: string): string {
  return path.replace(/\\/g, "/").replace(/^\.\//, "");
}

function stem(path: string): string {
  const i = path.lastIndexOf(".");
  return i >= 0 ? path.slice(0, i) : path;
}

/**
 * Find a file's coverage, matching by the longest shared path suffix.
 *
 * Coverage is reported against whatever the tests ran — compiled output, an
 * absolute path, a path relative to a different root. The ledger holds project
 * paths. Requiring them to be equal would make this check impossible to satisfy
 * on any project with a build step, which is most of them.
 */
export function coverageFor(cov: Coverage, path: string): FileCoverage | null {
  const want = normalise(path);
  const direct = cov.get(want);
  if (direct) return direct;
  const wantParts = want.split("/");
  let best: FileCoverage | null = null;
  let bestScore = 0;
  for (const [key, value] of cov) {
    const keyParts = key.split("/");
    let score = 0;
    while (
      score < wantParts.length &&
      score < keyParts.length &&
      stem(wantParts[wantParts.length - 1 - score]) === stem(keyParts[keyParts.length - 1 - score])
    ) {
      score++;
    }
    // One shared segment is a filename collision, not a match.
    if (score > bestScore && score >= 2) {
      bestScore = score;
      best = value;
    }
  }
  return best;

