/**
 * Test demonstrating the defect where coverageFor fails to match src/bar.ts
 * with dist-test/src/bar.js when the extensions differ (.ts vs .js).
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { coverageFor, parseLcov } from "../src/coverage.js";

const LCOV_WITH_DIST_TEST = `TN:
SF:dist-test/src/bar.js
DA:5,3
DA:6,0
DA:7,2
end_of_record
`;

describe("coverageFor with dist-test prefix", () => {
  it("should match src/bar.ts to dist-test/src/bar.js", () => {
    const cov = parseLcov(LCOV_WITH_DIST_TEST);
    const result = coverageFor(cov, "src/bar.ts");
    assert.ok(result !== null, "should match src/bar.ts to dist-test/src/bar.js despite .ts vs .js extension");
    assert.equal(result!.lines.get(5), 3);
    assert.equal(result!.lines.get(6), 0);
    assert.equal(result!.lines.get(7), 2);
  });

  it("handles files starting with a dot by stripping extension", () => {
    // If the stem condition is i > 0 instead of i >= 0, this would fail
    const cov = parseLcov("SF:vendor/.hidden.js\nDA:1,5\nend_of_record\n");
    const result = coverageFor(cov, "src/.hidden.ts");
    assert.ok(result !== null, "should match .hidden.ts to .hidden.js");
    assert.equal(result!.lines.get(1), 5);
  });
});

