    assert.equal(parseLcov("DA:1,1\n").size, 0, "records before any SF belong to no file");
  });
});

describe("matching a project path to a coverage path", () => {
  it("matches through a build directory", () => {
    // Coverage is reported against whatever ran — usually compiled output.
    // Requiring equality would make this check impossible on any project with
    // a build step, which is most of them.
    const cov = parseLcov(LCOV);
    assert.ok(coverageFor(cov, "src/files.ts".replace(".ts", ".js")));
    assert.ok(coverageFor(cov, "src/files.js"));
  });

  it("refuses a match on the filename alone", () => {
    // `files.js` in two different directories is a collision, not a match, and
    // reporting one file's coverage for another would be worse than silence.
    const cov = parseLcov("SF:vendor/deep/nested/files.js\nDA:1,1\nend_of_record\n");
    assert.equal(coverageFor(cov, "files.js"), null);
  });

  it("normalises separators and a leading ./", () => {
    assert.equal(normalise(String.raw`./src\a.ts`), "src/a.ts");
  });
});

describe("what counts as unproven", () => {
  it("flags a changed line the tests never executed", () => {
    const cov = parseLcov(LCOV);
    const bad = unprovenIn(cov, "src/files.js", [11]);
    assert.deepEqual(bad?.deadLines, [11]);
  });

  it("flags a line that ran but whose branch never went one way", () => {
    // This is the guard that returns false and is never tripped. Line coverage
    // alone calls it covered — the `if` executed. Only the branch count says
    // the behaviour was never shown.
    const cov = parseLcov(LCOV);
    const bad = unprovenIn(cov, "src/files.js", [12]);
    assert.deepEqual(bad?.deadBranches, [12]);
    assert.deepEqual(bad?.deadLines, []);
  });

  it("accepts a line that ran with every branch taken", () => {
    const cov = parseLcov(LCOV);
    assert.equal(unprovenIn(cov, "src/files.js", [10, 14]), null);
  });

  it("says nothing about a line the tool never instrumented", () => {
    // lcov lists only what the tool considers executable, so a type, an
    // import or a declaration is simply absent. Silence means "not
    // instrumented", not "not run", and failing on it would refuse honest work.
    const cov = parseLcov(LCOV);
    assert.equal(unprovenIn(cov, "src/files.js", [99]), null);
  });

  it("is handed a report in source coordinates, or it can match nothing", () => {
    // The suite compiles to dist-test/ and the ledger names src/*.ts. Without
    // source maps the report says `dist-test/src/bar.js` with compiled line
    // numbers, `coverageFor` matches by path suffix, and `bar.js` never
    // matches `bar.ts` — every work-proven row this project ever issued read
    // "0 changed file(s) executed by the tests" and passed. Both halves are
    // needed: tsc has to emit the maps and node has to be told to read them.
    const tsconfig = JSON.parse(readFileSync("tsconfig.test.json", "utf8")) as {
      compilerOptions?: { sourceMap?: boolean };
    };
    assert.equal(tsconfig.compilerOptions?.sourceMap, true, "tsconfig.test.json must emit source maps");
    const runner = readFileSync("test-run.mjs", "utf8");
    assert.match(runner, /"--enable-source-maps"/, "test-run.mjs must pass --enable-source-maps");
    assert.match(runner, /"--experimental-test-coverage"/);
  });

  it("says nothing about a file absent from the report", () => {
    const cov = parseLcov(LCOV);
    assert.equal(unprovenIn(cov, "ui/styles.css", [1, 2, 3]), null);
  });
});

/**
 * Test for the src: coverage path matching ignores file extensions.
 *
 * This test demonstrates the bug where coverageFor fails to match source
 * files (src/bar.ts) with their compiled counterparts (dist-test/src/bar.js)
 * because the extension comparison (.ts vs .js) prevents a match.
 */
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { coverageFor, parseLcov } from "../src/coverage.js";

const SOURCE_COV = `TN:
SF:dist-test/src/bar.js
DA:5,3
DA:6,0
DA:7,2
end_of_record
`;

describe("coverage path matching with extension differences", () => {
  it("matches source files to compiled files when extensions differ", () => {
    // The ledger has src/bar.ts (source), coverage has dist-test/src/bar.js (compiled).
    // Without extension-aware matching, this returns null and the check passes.
    const cov = parseLcov(SOURCE_COV);
    const result = coverageFor(cov, "src/bar.ts");
    assert.ok(result !== null, "should match src/bar.ts to dist-test/src/bar.js despite .ts vs .js extension");
    assert.equal(result!.lines.get(5), 3);
  });

  it("matches when source path is shorter than coverage path", () => {
    // Coverage reports dist-test/src/bar.js but the ledger has src/bar.ts.
    // The matching needs to work when wantParts is a prefix of keyParts (excluding extension).
    const cov = parseLcov(SOURCE_COV);
    const result = coverageFor(cov, "src/bar.ts");
    assert.ok(result !== null);
  });

  it("still refuses matches on filename alone (collision protection)", () => {
    // Different directories with same filename should not match.
    const cov = parseLcov("SF:vendor/bar.js\nDA:1,1\nend_of_record\n");
    // src/bar.ts should not match vendor/bar.js
    assert.equal(coverageFor(cov, "src/bar.ts"), null);
  });
});

